[Form]
public class AVAQuotationOrdered extends FormRun
{
    QueryBuildRange ax2009quotationId_qbr;
    QuotationId     quotationId;
    boolean         last_ItemSum;
    [FormObservable]
    SalesLineAmount lineAmount;

}

public NDX_SalesLineQtyOrdered initSalesLineQtyOrdered()
{
    Args                args;
    SalesQuotationTable salesQuotationTable;
    SalesQuotationLine  salesQuotationLine;
    SalesLine           salesLine;
    ItemId              l_ItemId, l_ItemIdOld;
    NDX_SalesLineQtyOrdered l_salesLineQtyOrdered;
    SalesQty            qtyInQuotation;
    args = this.args();

    if(args.record() && args.record().TableId == tablenum(SalesQuotationTable))
    {
        salesQuotationTable = args.record();
        quotationId         = salesQuotationTable.QuotationId;

        //while select * from salesLine order by Itemid where salesLine.AVAQuotationId == quotationId && !salesLine.RevRecIsBundleComponent
        while select * from salesLine order by Itemid where salesLine.AVAQuotationId == quotationId && !salesLine.AVAItemSetComponent
        {
            qtyInQuotation = 0;

         /*  while select * from SalesQuotationLine where SalesQuotationLine.QuotationId == quotationId
            && SalesQuotationLine.ItemId == salesLine.ItemId
            {
                qtyInQuotation += SalesQuotationLine.SalesQty;
            }*/

            select sum(SalesQty) from salesQuotationLine
                group by ItemId, QuotationId
                where salesQuotationLine.ItemId == salesLine.ItemId
                   && salesQuotationLine.QuotationId == quotationId;

            qtyInQuotation = salesQuotationLine.salesQty;

            if(salesLine.ItemId == l_ItemId || !l_ItemId)
            {
                SalesLineQtyOrdered.Delta = 0;
                ttsbegin;
                SalesLineQtyOrdered.ItemId               = salesLine.ItemId;
                SalesLineQtyOrdered.SalesUnit            = salesLine.SalesUnit;
                SalesLineQtyOrdered.InQuotation          = qtyInQuotation;
                SalesLineQtyOrdered.InvoicedInTotal      = salesLine.invoicedInTotal();
                SalesLineQtyOrdered.DelieveredInTotal    = salesLine.deliveredInTotal();
                SalesLineQtyOrdered.DelieverRemaining    = salesLine.RemainInventPhysical;
                //SalesLineQtyOrdered.OnOrder              = salesLine.onOrderInSalesUnit();//salesLine.KCS_EditQty(false, SalesLineQtyOrdered.OnOrder);
                //SalesLineQtyOrdered.OnOrder              = salesLine.SalesQty + salesLine.RevRecBundleQty;
                SalesLineQtyOrdered.OnOrder              = salesLine.SalesQty + salesLine.AVAItemSetCompQtyPerSerie;
                SalesLineQtyOrdered.Delta                = SalesLineQtyOrdered.InQuotation - SalesLineQtyOrdered.OnOrder;
                //  SalesLineQtyOrdered.LineAmount           = salesLine.LineAmount + salesLine.RevRecBundleNetAmount;
                SalesLineQtyOrdered.LineAmount           = salesLine.LineAmount;
                SalesLineQtyOrdered.SalesId              = salesLine.SalesId;
                SalesLineQtyOrdered.insert();
                ttscommit;

                l_ItemIdOld = salesLine.ItemId;
            }
            else
            {
                //Altes Item Summe
                ttsbegin;
                l_salesLineQtyOrdered.clear();

                select sum(InvoicedInTotal), sum(DelieveredInTotal), sum(DelieverRemaining), sum(OnOrder), sum(LineAmount) from salesLineQtyOrdered
                    group by ItemId, SalesUnit
                    where salesLineQtyOrdered.ItemId == l_ItemIdOld
                       /*&& salesLineQtyOrdered.SalesUnit == salesLine.SalesUnit*/;

                l_salesLineQtyOrdered.ItemId               = SalesLineQtyOrdered.ItemId;
                l_salesLineQtyOrdered.SalesUnit            = SalesLineQtyOrdered.SalesUnit;

                l_salesLineQtyOrdered.InvoicedInTotal      = SalesLineQtyOrdered.invoicedInTotal;
                l_salesLineQtyOrdered.DelieveredInTotal    = SalesLineQtyOrdered.DelieveredInTotal;
                l_salesLineQtyOrdered.DelieverRemaining    = SalesLineQtyOrdered.DelieverRemaining;
                l_salesLineQtyOrdered.OnOrder              = SalesLineQtyOrdered.OnOrder;
                l_salesLineQtyOrdered.LineAmount           = SalesLineQtyOrdered.LineAmount;

                select sum(SalesQty) from salesQuotationLine
                    group by ItemId
                    where salesQuotationLine.QuotationId == quotationId
                       && salesQuotationLine.ItemId      == l_ItemIdOld;


                l_salesLineQtyOrdered.InQuotation = SalesQuotationLine.SalesQty;


                l_salesLineQtyOrdered.Delta     = l_salesLineQtyOrdered.InQuotation - l_salesLineQtyOrdered.OnOrder;
                l_salesLineQtyOrdered.SalesId = 'Summe';
                SalesLineQtyOrdered.data(l_salesLineQtyOrdered);
                SalesLineQtyOrdered.insert();
                ttscommit;

                SalesLineQtyOrdered.Delta = 0;
                //Neues Item Einzeln
                ttsbegin;
                SalesLineQtyOrdered.ItemId               = salesLine.ItemId;
                SalesLineQtyOrdered.SalesUnit            = salesLine.SalesUnit;
                SalesLineQtyOrdered.InQuotation          = qtyInQuotation;
                SalesLineQtyOrdered.InvoicedInTotal      = salesLine.invoicedInTotal();
                SalesLineQtyOrdered.DelieveredInTotal    = salesLine.deliveredInTotal();
                SalesLineQtyOrdered.DelieverRemaining    = salesLine.RemainInventPhysical;
                //SalesLineQtyOrdered.OnOrder              = salesLine.onOrderInSalesUnit();//salesLine.KCS_EditQty(false, SalesLineQtyOrdered.OnOrder);
                //SalesLineQtyOrdered.OnOrder              = salesLine.SalesQty + salesLine.RevRecBundleQty;
                SalesLineQtyOrdered.OnOrder              = salesLine.SalesQty + salesLine.AVAItemSetCompQtyPerSerie;
                SalesLineQtyOrdered.Delta                = SalesLineQtyOrdered.InQuotation - SalesLineQtyOrdered.OnOrder;
                //SalesLineQtyOrdered.LineAmount           = salesLine.LineAmount + salesLine.RevRecBundleNetAmount;
                SalesLineQtyOrdered.LineAmount           = salesLine.LineAmount;
                SalesLineQtyOrdered.SalesId              = salesLine.SalesId;
                SalesLineQtyOrdered.insert();
                ttscommit;

                l_ItemIdOld = salesLine.ItemId;
            }

            l_ItemId = salesLine.ItemId;
        }
        //Altes Item Summe
        ttsbegin;
        l_salesLineQtyOrdered.clear();

        select sum(invoicedInTotal), sum(DelieveredInTotal), sum(DelieverRemaining), sum (OnOrder), sum(LineAmount) from SalesLineQtyOrdered
            group by ItemId, SalesUnit
            where salesLineQtyOrdered.ItemId == l_ItemIdOld;


        l_salesLineQtyOrdered.ItemId               = SalesLineQtyOrdered.ItemId;
        l_salesLineQtyOrdered.SalesUnit            = SalesLineQtyOrdered.SalesUnit;

        l_salesLineQtyOrdered.InvoicedInTotal      = SalesLineQtyOrdered.invoicedInTotal;
        l_salesLineQtyOrdered.DelieveredInTotal    = SalesLineQtyOrdered.DelieveredInTotal;
        l_salesLineQtyOrdered.DelieverRemaining    = SalesLineQtyOrdered.DelieverRemaining;
        l_salesLineQtyOrdered.OnOrder              = SalesLineQtyOrdered.OnOrder;
        l_salesLineQtyOrdered.LineAmount           = SalesLineQtyOrdered.LineAmount;

        select sum(SalesQty) from salesQuotationLine
            group by QuotationId, ItemId
            where salesQuotationLine.QuotationId == quotationId  
            && salesQuotationLine.ItemId == l_ItemIdOld;

        l_salesLineQtyOrdered.InQuotation = SalesQuotationLine.SalesQty;

        l_salesLineQtyOrdered.Delta     = l_salesLineQtyOrdered.InQuotation - l_salesLineQtyOrdered.OnOrder;
        l_salesLineQtyOrdered.SalesId = 'Summe';
        SalesLineQtyOrdered.data(l_salesLineQtyOrdered);
        SalesLineQtyOrdered.insert();
        ttscommit;

        select sum(LineAmount) from salesLineQtyOrdered
            group by SalesId
            where SalesLineQtyOrdered.SalesId == 'Summe';

        lineAmount = SalesLineQtyOrdered.LineAmount;


        SalesLineQtyOrdered_DS.executeQuery();
    }
    return l_salesLineQtyOrdered;
}

public void init()
{
    NDX_SalesLineQtyOrdered     l_salesLineQtyOrdered;
    super();

    l_salesLineQtyOrdered.data(this.initSalesLineQtyOrdered());
    ttsbegin;
    l_salesLineQtyOrdered.clear();
    l_salesLineQtyOrdered.SalesId = 'Gesamt';
    l_salesLineQtyOrdered.LineAmount = element.getSum();
    SalesLineQtyOrdered.data(l_salesLineQtyOrdered);
    SalesLineQtyOrdered.insert();
    ttscommit;
}

public void getTotalAmount()
{
    AmountMST totalAmount_loc = orderSum.realValue() + quotationSum.realValue();
    TotalSum.realValue(totalAmount_loc);
}

public void getAX2009Amount()
{
    // Copy the query
    Query query = new Query(AVAAX2009Ordered_ds.queryRun().query());

    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(AVAAX2009Ordered));
    QueryRun qr;
    AVAAX2009Ordered summedTrans;

    // Sum LineAmountMst
    qbds.addSelectionField(fieldNum(AVAAX2009Ordered, AX2009Amount), SelectionField::Sum);

    qr = new QueryRun(query);
    // Run the query
    qr.next();

    // Get the data
    summedTrans = qr.get(tableNum(AVAAX2009Ordered));

    // Set the new sum to the control
    QuotationSum.realValue(summedTrans.AX2009Amount);
}

public void displayOption(Common _record, FormRowDisplayOption _options)
{
    NDX_SalesLineQtyOrdered l_salesLineQtyOrdered = _record;

    if (l_salesLineQtyOrdered.SalesId == 'Summe')
    {
        _options.backColor(WinApi::RGB2int(255,255,0)); 
    }
    if (l_salesLineQtyOrdered.SalesId == 'Gesamt')
    {
        _options.backColor(WinApi::RGB2int(178,255,84)); 
    }
    super(_record, _options);
}

/// <summary>
/// init method
/// </summary>
public void init()
{
    QueryBuildDataSource ax2009ordered_qbds;

    super();

    ax2009ordered_qbds      = AVAAX2009Ordered_q.dataSourceTable(tableNum(AVAAX2009Ordered));
    ax2009quotationId_qbr   = ax2009ordered_qbds.addRange(fieldNum(AVAAX2009Ordered, AX2009QuotationId));
}

/// <summary>
/// executeQuery method
/// </summary>
public void executeQuery()
{
    ax2009quotationId_qbr.value(queryValue(quotationId));

    super();

    element.getAX2009Amount();
    element.getTotalAmount();
}
